    test('XdrEnvelopeType ENVELOPE_TYPE_TX_V0 renders as tx_v0', () {
      var member = XdrEnvelopeType.ENVELOPE_TYPE_TX_V0;
      expect(member.value, 0);
      expect(member.toXdrJsonValue(), 'tx_v0');
      expect(member.toXdrJson(), '"tx_v0"');
      var parsed = XdrEnvelopeType.fromXdrJson('"tx_v0"');
      expect(parsed.value, 0);
