            (XdrPublicKey(XdrPublicKeyType.PUBLIC_KEY_TYPE_ED25519)
              ..ed25519 = XdrUint256(
                Uint8List.fromList(List<int>.filled(32, 0xAB)),
              )),
          ),
        ));
      expect(
        (original.toXdrJsonValue() as Map<String, Object?>).keys.single,
        'live',
      );
      var json = original.toXdrJson();
      var fromDocument = XdrHotArchiveBucketEntry.fromXdrJson(json);
      expect(fromDocument.toXdrJson(), json);
      expect(
        fromDocument.toBase64EncodedXdrString(),
        original.toBase64EncodedXdrString(),
      );
      var fromTree = XdrHotArchiveBucketEntry.fromXdrJsonValue(
        original.toXdrJsonValue(),
      );
      expect(fromTree.toXdrJsonValue(), original.toXdrJsonValue());
      expect(
        fromTree.toBase64EncodedXdrString(),
        original.toBase64EncodedXdrString(),
      );
    });
    test('XdrHotArchiveBucketEntry metaentry arm round trip', () {
      var original = XdrHotArchiveBucketEntry(
        XdrHotArchiveBucketEntryType.HOT_ARCHIVE_METAENTRY,
      );
      original.metaEntry = XdrBucketMetadata(
        XdrUint32(42),
        XdrBucketMetadataExt(0),
      );
      expect(
        (original.toXdrJsonValue() as Map<String, Object?>).keys.single,
        'metaentry',
      );
      var json = original.toXdrJson();
      var fromDocument = XdrHotArchiveBucketEntry.fromXdrJson(json);
      expect(fromDocument.toXdrJson(), json);
      expect(
        fromDocument.toBase64EncodedXdrString(),
        original.toBase64EncodedXdrString(),
      );
      var fromTree = XdrHotArchiveBucketEntry.fromXdrJsonValue(
        original.toXdrJsonValue(),
      );
      expect(fromTree.toXdrJsonValue(), original.toXdrJsonValue());
      expect(
        fromTree.toBase64EncodedXdrString(),
        original.toBase64EncodedXdrString(),
      );
    });
    test('XdrHotArchiveBucketEntry rejects an undeclared discriminant', () {
      expect(
        () => XdrHotArchiveBucketEntry(
          XdrHotArchiveBucketEntryType(2),
        ).toXdrJsonValue(),
        throwsA(isA<FormatException>()),
      );
    });
    test('XdrHotArchiveBucketEntry rejects an undeclared arm key', () {
      expect(
        () => XdrHotArchiveBucketEntry.fromXdrJsonValue(<String, Object?>{
          'xdr_json_undeclared_arm': null,
        }),
        throwsA(isA<FormatException>()),
      );
    });
  });
}
